import type { Node, NodeData, NodeId, Position, SavedState, SelectNodeOptions, TreeElementOptions } from "tree-element"

import TreeElement from "tree-element";

import type { JQTreeIconElement, JQTreeOptions } from "./jqtreeOptions";

import triggerJQueryEvent from "./triggerJQueryEvent";
import __version__ from "./version";

type IconElement = HTMLElement | string

interface LoadFailedEvent {
    response: Response;
}

interface LoadingDataEvent {
    $el: JQuery;
    isLoading: boolean;
    node: Node | null;
}

type OnCreateLi = (node: Node, el: HTMLElement, isSelected: boolean) => void;
type OnFinishOpenNode = (node: Node) => void;
type OnIsMoveHandle = (el: HTMLElement) => boolean;

const NODE_PARAM_IS_EMPTY = "Node parameter is empty";
const PARAM_IS_EMPTY = "Parameter is empty: ";

export class JqTreeWidget {
    [key: string]: unknown;

    private _element: JQuery;
    private _inputOptions: Partial<JQTreeOptions>;
    private _treeElement: TreeElement;

    constructor(el: HTMLElement, options: Partial<JQTreeOptions>) {
        this._element = jQuery(el);

        this._inputOptions = options;
    }

    public addNodeAfter(
        newNodeInfo: NodeData,
        existingNode: Node,
    ): Node | null {
        return this._treeElement.addNodeAfter(newNodeInfo, existingNode);
    }

    public addNodeBefore(
        newNodeInfo: NodeData,
        existingNode?: Node,
    ): Node | null {
        if (!existingNode) {
            throw Error(PARAM_IS_EMPTY + "existingNode");
        }

        return this._treeElement.addNodeBefore(newNodeInfo, existingNode);
    }

    public addParentNode(
        newNodeInfo: NodeData,
        existingNode?: Node,
    ): Node | null {
        if (!existingNode) {
            throw Error(PARAM_IS_EMPTY + "existingNode");
        }

        return this._treeElement.addParentNode(newNodeInfo, existingNode);
    }

    public addToSelection(node?: Node, mustSetFocus?: boolean): JQuery {
        if (!node) {
            throw Error(NODE_PARAM_IS_EMPTY);
        }

        this._treeElement.addToSelection(node, mustSetFocus);
        return this._element;
    }

    public appendNode(newNodeInfo: NodeData, parentNodeParam?: Node): Node {
        const parentNode = parentNodeParam ?? this._treeElement.tree;

        return this._treeElement.appendNode(newNodeInfo, parentNode);
    }

    public closeNode(node?: Node, slideParam?: boolean | null): JQuery {
        if (!node) {
            throw Error(NODE_PARAM_IS_EMPTY);
        }

        this._treeElement.closeNode(node, slideParam ?? undefined);

        return this._element;
    }

    public deinit(): void {
        this._element.off();
        this._treeElement.deinit();
    }

    public destroy(): void {
        this.deinit();
    }

    public getNodeByCallback(callback: (node: Node) => boolean): Node | null {
        return this._treeElement.getNodeByCallback(callback);
    }

    public getNodeByHtmlElement(
        inputElement: HTMLElement | JQuery,
    ): Node | null {
        const element =
            inputElement instanceof HTMLElement
                ? inputElement
                : inputElement.get(0);

        if (!element) {
            return null;
        }

        return this._treeElement.getNode(element);
    }

    public getNodeById(nodeId: NodeId): Node | null {
        return this._treeElement.getNodeById(nodeId);
    }

    public getNodeByName(name: string): Node | null {
        return this._treeElement.getNodeByName(name);
    }

    public getNodeByNameMustExist(name: string): Node {
        return this._treeElement.getNodeByNameMustExist(name);
    }

    public getNodesByProperty(key: string, value: unknown): Node[] {
        return this._treeElement.getNodesByProperty(key, value);
    }

    public getSelectedNode(): false | Node {
        return this._treeElement.getSelectedNode();
    }

    public getSelectedNodes(): Node[] {
        return this._treeElement.getSelectedNodes();
    }

    public getState(): null | SavedState {
        return this._treeElement.getState();
    }

    public getStateFromStorage(): null | SavedState {
        return this._treeElement.getStateFromStorage();
    }

    public getTree(): Node {
        return this._treeElement.getTree();
    }

    public getVersion(): string {
        return __version__;
    }

    public init(): void {
        const htmlElement = this._element.get(0) as HTMLElement;

        this._element.on("tree.loading_data", this._handleLoadingDataEvent.bind(this));
        this._element.on("tree.load_failed", this._handleLoadFailedEvent.bind(this));

        const options = this._transformInputOptions();

        const treeElement = new TreeElement(
            {
                ...options,
                classPrefix: "jqtree",
                commonClassName: "jqtree_common",
                htmlElement,
                overrideTriggerEventProvider: triggerJQueryEvent,
                treeClassName: "jqtree-tree"
            }
        );

        this._treeElement = treeElement;
    }

    public isDragging(): boolean {
        return this._treeElement.isDragging();
    }

    public isNodeSelected(node?: Node): boolean {
        if (!node) {
            throw Error(NODE_PARAM_IS_EMPTY);
        }

        return this._treeElement.isNodeSelected(node);
    }

    public loadData(data: NodeData[], parentNode?: Node): JQuery {
        this._treeElement.loadData(data, parentNode);
        return this._element;
    }

    /*
    signatures:
    - loadDataFromUrl(url, parent_node=null, on_finished=null)
        loadDataFromUrl('/my_data');
        loadDataFromUrl('/my_data', node1);
        loadDataFromUrl('/my_data', node1, function() { console.log('finished'); });
        loadDataFromUrl('/my_data', null, function() { console.log('finished'); });
 
    - loadDataFromUrl(parent_node=null, on_finished=null)
        loadDataFromUrl();
        loadDataFromUrl(node1);
        loadDataFromUrl(null, function() { console.log('finished'); });
        loadDataFromUrl(node1, function() { console.log('finished'); });
    */
    public loadDataFromUrl(
        param1?: Node | string,
        param2?: (() => void) | Node,
        param3?: () => void,
    ): JQuery {
        let parentNode: Node | undefined;
        let onFinishedLoading: (() => void) | undefined;
        let url: string | undefined;

        // first parameter is url
        if (typeof param1 === "string") {
            url = param1;
            parentNode = param2 as (Node | undefined);
            onFinishedLoading = param3;

        } else {
            // first parameter is not url
            parentNode = param1;
            onFinishedLoading = param2 as (() => void) | undefined;
        }

        this._treeElement.loadDataFromUrl(url, parentNode)
            .then(() => {
                if (onFinishedLoading) {
                    onFinishedLoading();
                }
            })
            .catch((error: unknown) => {
                throw error;
            });

        return this._element;
    }

    public moveDown(): JQuery {
        this._treeElement.moveDown();

        return this._element;
    }

    public moveNode(
        node?: Node,
        targetNode?: Node,
        position?: Position,
    ): JQuery {
        if (!node) {
            throw Error(NODE_PARAM_IS_EMPTY);
        }

        if (!targetNode) {
            throw Error(PARAM_IS_EMPTY + "targetNode");
        }

        if (!position) {
            throw Error(PARAM_IS_EMPTY + "position");
        }

        this._treeElement.moveNode(node, targetNode, position);

        return this._element;
    }

    public moveUp(): JQuery {
        this._treeElement.moveUp();
        return this._element;
    }

    public openNode(
        node?: Node,
        param1?: boolean | OnFinishOpenNode,
        param2?: OnFinishOpenNode,
    ): JQuery {
        if (!node) {
            throw Error(NODE_PARAM_IS_EMPTY);
        }

        let onFinished: null | OnFinishOpenNode = null;
        let slide: boolean | undefined = undefined;

        if (typeof param1 === "function") {
            onFinished = param1;
            slide = param2 as boolean | undefined;
        } else {
            slide = param1;
        }

        void this._treeElement.openNode(node, slide).then(() => {
            if (onFinished) {
                onFinished(node);
            }
        });
        return this._element;
    }

    public prependNode(newNodeInfo: NodeData, parentNodeParam?: Node): Node {
        const parentNode = parentNodeParam ?? this._treeElement.tree;

        return this._treeElement.prependNode(newNodeInfo, parentNode);
    }

    public refresh(): JQuery {
        this._treeElement.refresh();
        return this._element;
    }

    public reload(onFinished?: () => void): JQuery {
        this._treeElement.loadDataFromUrl(undefined, undefined).then(
            () => {
                if (onFinished) {
                    onFinished();
                }
            }
        ).catch((error: unknown) => {
            throw error;
        });
        return this._element;
    }

    public removeFromSelection(node?: Node): JQuery {
        if (!node) {
            throw Error(NODE_PARAM_IS_EMPTY);
        }

        this._treeElement.removeFromSelection(node);
        return this._element;
    }

    public removeNode(node?: Node): JQuery {
        if (!node) {
            throw Error(NODE_PARAM_IS_EMPTY);
        }

        if (!node.parent) {
            throw Error("Node has no parent");
        }

        this._treeElement.removeNode(node);
        return this._element;
    }

    public scrollToNode(node?: Node): JQuery {
        if (!node) {
            throw Error(NODE_PARAM_IS_EMPTY);
        }

        this._treeElement.scrollToNode(node);
        return this._element;
    }

    public selectNode(
        node: Node | null,
        optionsParam?: SelectNodeOptions,
    ): JQuery {
        this._treeElement.selectNode(node, optionsParam);
        return this._element;
    }

    public setOption(option: string, value: unknown): JQuery {
        this._treeElement.setOption(option, value);
        return this._element;
    }

    public setState(state?: SavedState): JQuery {
        if (state) {
            this._treeElement.setState(state);
        }

        return this._element;
    }

    public toggle(node?: Node, slideParam: boolean | null = null): JQuery {
        if (!node) {
            throw Error(NODE_PARAM_IS_EMPTY);
        }

        this._treeElement.toggle(node, slideParam);
        return this._element;
    }

    public toJson(): string {
        return this._treeElement.toJson();
    }

    public updateNode(node?: Node, data?: NodeData): JQuery {
        if (!node) {
            throw Error(NODE_PARAM_IS_EMPTY);
        }

        if (!data) {
            return this._element;
        }

        this._treeElement.updateNode(node, data);
        return this._element;
    }

    private _handleLoadFailedEvent(e: JQuery.TriggeredEvent) {
        const jqTreeOnLoadFailed = this._inputOptions.onLoadFailed;

        if (jqTreeOnLoadFailed) {
            const { response } = e as unknown as LoadFailedEvent;
            jqTreeOnLoadFailed(response);
        }
    }

    private _handleLoadingDataEvent(e: JQuery.TriggeredEvent) {
        const jqTreeOnLoading = this._inputOptions.onLoading;

        if (jqTreeOnLoading) {
            const { $el, isLoading, node } = e as unknown as LoadingDataEvent;
            jqTreeOnLoading(isLoading, node ?? undefined, $el)
        }
    }

    private _transformInputOptions(): Partial<TreeElementOptions> {
        function convertToIconElement(jqtreeIconElement: JQTreeIconElement | undefined) {
            if (jqtreeIconElement instanceof jQuery) {
                return (jqtreeIconElement as JQuery).get(0);
            } else {
                return jqtreeIconElement as IconElement;
            }
        }

        const closedIcon = convertToIconElement(this._inputOptions.closedIcon);
        const openedIcon = convertToIconElement(this._inputOptions.openedIcon);

        let onCreateLi: OnCreateLi | undefined = undefined;
        const jqTreeOnCreateLi = this._inputOptions.onCreateLi;

        if (jqTreeOnCreateLi) {
            onCreateLi = (node: Node, el: HTMLElement, isSelected: boolean) => {
                jqTreeOnCreateLi(node, jQuery(el), isSelected);
            };
        }

        let onIsMoveHandle: OnIsMoveHandle | undefined = undefined;
        const jqTreeOnIsMoveHandle = this._inputOptions.onIsMoveHandle;

        if (jqTreeOnIsMoveHandle) {
            onIsMoveHandle = (el: HTMLElement) => jqTreeOnIsMoveHandle(jQuery(el))
        }

        return {
            ...this._inputOptions,
            closedIcon,
            onCreateLi,
            onIsMoveHandle,
            openedIcon,
        }
    }
}

const register = (): void => {
    const getWidgetData = (
        el: HTMLElement,
        dataKey: string,
    ): JqTreeWidget | null => {
        const widget = jQuery.data(el, dataKey) as unknown;

        if (widget && widget instanceof JqTreeWidget) {
            return widget;
        } else {
            return null;
        }
    };

    const createWidget = ($el: JQuery, options: null | Partial<JQTreeOptions>): JQuery => {
        for (const el of $el.get()) {
            const existingWidget = getWidgetData(el, "jqtree");

            if (!existingWidget) {
                const widget = new JqTreeWidget(el, options ?? {});

                if (!jQuery.data(el, "jqtree")) {
                    jQuery.data(el, "jqtree", widget);
                }

                // Call init after setting data, so we can call methods
                widget.init();
            }
        }

        return $el;
    };

    const destroyWidget = ($el: JQuery): void => {
        for (const el of $el.get()) {
            const widget = getWidgetData(el, "jqtree");

            if (widget) {
                widget.destroy();
            }

            jQuery.removeData(el, "jqtree");
        }
    };

    const callFunction = (
        $el: JQuery,
        functionName: string,
        args: unknown[],
    ): unknown => {
        let result = null;

        for (const el of $el.get()) {
            const widget = jQuery.data(el, "jqtree") as unknown;

            if (widget && widget instanceof JqTreeWidget) {
                const widgetFunction = widget[functionName];

                if (widgetFunction && typeof widgetFunction === "function") {
                    result = widgetFunction.apply(widget, args) as unknown;
                }
            }
        }

        return result;
    };

    // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
    (jQuery.fn as any).tree = function (
        this: JQuery,
        argument1: unknown,
        ...args: unknown[]
    ) {
        if (!argument1) {
            return createWidget(this, null);
        } else if (typeof argument1 === "object") {
            const options = argument1 as unknown;
            return createWidget(this, options as JQTreeOptions);
        } else if (typeof argument1 === "string" && argument1[0] !== "_") {
            const functionName = argument1;

            if (argument1 === "destroy") {
                destroyWidget(this);
                return undefined;
            } else {
                return callFunction(this, functionName, args);
            }
        } else {
            return undefined;
        }
    };
};

register();
